/**
 * Mermaid Integration Loader para md_server
 * Carrega a biblioteca Mermaid.js via CDN ou executa renderização nativa de diagramas.
 */
(function() {
  var loadPromise = null;

  window.loadMermaidLibrary = function() {
    if (window.mermaid) {
      return Promise.resolve(window.mermaid);
    }
    if (loadPromise) {
      return loadPromise;
    }

    loadPromise = new Promise(function(resolve, reject) {
      var script = document.createElement('script');
      script.src = 'https://cdn.jsdelivr.net/npm/mermaid@10/dist/mermaid.min.js';
      script.async = true;
      script.onload = function() {
        if (window.mermaid) {
          resolve(window.mermaid);
        } else {
          reject(new Error('Mermaid não encontrado após carregamento'));
        }
      };
      script.onerror = function() {
        reject(new Error('Falha ao carregar Mermaid.js da CDN'));
      };
      document.head.appendChild(script);
    });

    return loadPromise;
  };
})();
